examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    Row(verticalAlignment = Alignment.CenterVertically) {
        Column(modifier = Modifier.weight(1f)) {
            MonarchText(text = {{title}}, style = MonarchTextStyle.Title)
            MonarchText(text = {{description}}, style = MonarchTextStyle.Body)
        }
        MonarchButton(text = "Support", onClick = {}, variant = MonarchButtonVariant.Link)
    }
    MonarchBanner(title = "Degraded performance", message = null, tone = MonarchTone.Warning)
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        Box(modifier = Modifier.weight(1f)) {
            MonarchStatCard(label = "Uptime · 30d", text = "{{overallUptimePercent|raw}}%")
        }
        Box(modifier = Modifier.weight(1f)) {
            MonarchStatCard(label = "Services", text = "{{kpis.services|raw}}")
        }
        Box(modifier = Modifier.weight(1f)) {
            MonarchStatCard(label = "Active incidents", text = "{{kpis.activeIncidents|raw}}", tone = MonarchTone.Danger)
        }
    }
    MonarchText(text = "Active incidents", style = MonarchTextStyle.Heading)
    Column(
        modifier = Modifier.fillMaxWidth().border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.md).padding(MonarchTheme.spacing.space3),
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
    ) {
        MonarchText(text = {{activeIncident.title}}, style = MonarchTextStyle.BodyStrong)
        Row(verticalAlignment = Alignment.CenterVertically) {
            MonarchText(text = "Major · {{activeIncident.component|raw}} · ${stamp({{activeIncident.openedAt|millis}})}", modifier = Modifier.weight(1f), style = MonarchTextStyle.Caption)
            MonarchStatusBadge(definition = MonarchStatusDefinition(label = "Investigating", tone = MonarchTone.Warning, icon = { MonarchIcon(SampleIcons.Warning, null) }), size = MonarchStatusBadgeSize.Sm)
        }
        MonarchIncidentTimeline(
            updates = listOf(
                MonarchIncidentUpdate(id = "1", stage = MonarchIncidentStage.{{activeIncident.updates.0.stage|pascal}}, body = {{activeIncident.updates.0.body}}, time = {{activeIncident.updates.0.time|millis}}, automated = {{activeIncident.updates.0.automated}}),
                MonarchIncidentUpdate(id = "2", stage = MonarchIncidentStage.{{activeIncident.updates.1.stage|pascal}}, body = {{activeIncident.updates.1.body}}, time = {{activeIncident.updates.1.time|millis}}, automated = {{activeIncident.updates.1.automated}}),
            ),
        )
    }
    MonarchText(text = "Services", style = MonarchTextStyle.Heading)
    MonarchText(text = {{group}}, style = MonarchTextStyle.Label)
    Column(
        modifier = Modifier.fillMaxWidth().border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.md).padding(MonarchTheme.spacing.space3),
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
    ) {
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                MonarchText(text = {{services.0.name}}, style = MonarchTextStyle.BodyStrong)
                MonarchText(text = "{{services.0.responseTimeMs|raw}} ms", style = MonarchTextStyle.Caption)
                Spacer(modifier = Modifier.weight(1f))
                MonarchStatusBadge(definition = states.getValue({{services.0.state}}), size = MonarchStatusBadgeSize.Sm)
            }
            MonarchUptimeBar(segments = days(mapOf({{services.0.history.0.day}} to MonarchUptimeBarStatus.{{services.0.history.0.state|pascal}})), summary = {{services.0.name}} + ", {{services.0.uptimePercent|raw}}% uptime", overallUptime = {{services.0.uptimePercent|double}}, startLabel = "30 days ago", endLabel = "Today", size = MonarchUptimeBarSize.Sm)
        }
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                MonarchText(text = {{services.1.name}}, style = MonarchTextStyle.BodyStrong)
                MonarchText(text = "{{services.1.responseTimeMs|raw}} ms", style = MonarchTextStyle.Caption)
                Spacer(modifier = Modifier.weight(1f))
                MonarchStatusBadge(definition = states.getValue({{services.1.state}}), size = MonarchStatusBadgeSize.Sm)
            }
            MonarchUptimeBar(segments = days(mapOf({{services.1.history.0.day}} to MonarchUptimeBarStatus.{{services.1.history.0.state|pascal}}, {{services.1.history.1.day}} to MonarchUptimeBarStatus.{{services.1.history.1.state|pascal}})), summary = {{services.1.name}} + ", {{services.1.uptimePercent|raw}}% uptime", overallUptime = {{services.1.uptimePercent|double}}, startLabel = "30 days ago", endLabel = "Today", size = MonarchUptimeBarSize.Sm)
        }
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                MonarchText(text = {{services.2.name}}, style = MonarchTextStyle.BodyStrong)
                MonarchText(text = "{{services.2.responseTimeMs|raw}} ms", style = MonarchTextStyle.Caption)
                Spacer(modifier = Modifier.weight(1f))
                MonarchStatusBadge(definition = states.getValue({{services.2.state}}), size = MonarchStatusBadgeSize.Sm)
            }
            MonarchUptimeBar(segments = days(emptyMap()), summary = {{services.2.name}} + ", {{services.2.uptimePercent|raw}}% uptime", overallUptime = {{services.2.uptimePercent|double}}, startLabel = "30 days ago", endLabel = "Today", size = MonarchUptimeBarSize.Sm)
        }
    }
    Column(
        modifier = Modifier.fillMaxWidth().border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.md).padding(MonarchTheme.spacing.space3),
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
    ) {
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                Column(modifier = Modifier.weight(1f)) {
                    MonarchText(text = {{services.3.name}}, style = MonarchTextStyle.BodyStrong)
                    MonarchText(text = {{services.3.description}}, style = MonarchTextStyle.Caption)
                }
                MonarchStatusBadge(definition = states.getValue({{services.3.state}}), size = MonarchStatusBadgeSize.Sm)
            }
            MonarchUptimeBar(segments = days(mapOf({{services.3.history.0.day}} to MonarchUptimeBarStatus.{{services.3.history.0.state|pascal}})), summary = {{services.3.name}} + ", {{services.3.uptimePercent|raw}}% uptime", overallUptime = {{services.3.uptimePercent|double}}, startLabel = "30 days ago", endLabel = "Today", size = MonarchUptimeBarSize.Sm)
        }
    }
    FlowRow(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3), verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1), itemVerticalAlignment = Alignment.CenterVertically) {
        listOf(
            MonarchTheme.colors.successSolid to "Operational",
            MonarchTheme.colors.warningSolid to "Degraded",
            MonarchTheme.colors.dangerSolid to "Down",
            MonarchTheme.colors.infoSolid to "Maintenance",
            MonarchTheme.colors.bgMuted to "No data",
        ).forEach { (color, label) ->
            Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1), verticalAlignment = Alignment.CenterVertically) {
                Box(modifier = Modifier.size(8.dp).background(color))
                MonarchText(text = label, style = MonarchTextStyle.Caption)
            }
        }
    }
    MonarchText(text = "Past incidents", style = MonarchTextStyle.Heading)
    Column(
        modifier = Modifier.fillMaxWidth().border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.md).padding(MonarchTheme.spacing.space3),
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
    ) {
        MonarchText(text = {{pastIncident.title}}, style = MonarchTextStyle.BodyStrong)
        Row(verticalAlignment = Alignment.CenterVertically) {
            MonarchText(text = "Critical · {{pastIncident.component|raw}} · ${stamp({{pastIncident.openedAt|millis}})} · lasted ${{{pastIncident.durationSeconds}} / 60}m", modifier = Modifier.weight(1f), style = MonarchTextStyle.Caption)
            MonarchStatusBadge(definition = MonarchStatusDefinition(label = "Resolved", tone = MonarchTone.Success, icon = { MonarchIcon(SampleIcons.Success, null) }), size = MonarchStatusBadgeSize.Sm)
        }
        MonarchIncidentTimeline(
            updates = listOf(
                MonarchIncidentUpdate(id = "1", stage = MonarchIncidentStage.{{pastIncident.updates.0.stage|pascal}}, body = {{pastIncident.updates.0.body}}, time = {{pastIncident.updates.0.time|millis}}, automated = {{pastIncident.updates.0.automated}}),
                MonarchIncidentUpdate(id = "2", stage = MonarchIncidentStage.{{pastIncident.updates.1.stage|pascal}}, body = {{pastIncident.updates.1.body}}, time = {{pastIncident.updates.1.time|millis}}, automated = {{pastIncident.updates.1.automated}}),
            ),
        )
    }
    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchTextField(
            modifier = Modifier.fillMaxWidth(),
            value = email,
            onValueChange = { email = it },
            label = "Subscribe to updates",
            placeholder = "you@example.com",
            helperText = "Get an email when an incident is opened, updated or resolved.",
            required = true,
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email),
        )
        MonarchButton(text = "Subscribe", onClick = {}, variant = MonarchButtonVariant.Secondary)
    }
    MonarchText(text = "Updated ${({{now|millis}} - {{updatedAt|millis}}) / 60_000L} minute ago", style = MonarchTextStyle.Caption)
}

examples.setupTemplate:
val states = mapOf(
    "operational" to MonarchStatusDefinition(label = "Operational", tone = MonarchTone.Success, icon = { MonarchIcon(SampleIcons.Success, null) }),
    "degraded" to MonarchStatusDefinition(label = "Degraded", tone = MonarchTone.Warning, icon = { MonarchIcon(SampleIcons.Warning, null) }),
)
val stamp = { millis: Long ->
    SimpleDateFormat("MMM d, HH:mm 'UTC'", Locale.US).apply { timeZone = TimeZone.getTimeZone("UTC") }.format(Date(millis))
}
val days = { marks: Map<Int, MonarchUptimeBarStatus> ->
    (1..30).map { day ->
        MonarchUptimeBarSegment(id = "d$day", label = "Day $day", status = marks[day] ?: MonarchUptimeBarStatus.Operational)
    }
}
var email by rememberSaveable { mutableStateOf("") }

